Let me look at the commit `ecffca67` "Don't parse '}' as fill" and `bde1a607` "Simplify fill and alignment parsing". These are likely the fixes. Let me look at the current `parse_align` and compare with the fixed version.

Let me look at the current `parse_align` again:

```cpp
FMT_CONSTEXPR const Char* parse_align(const Char* begin, const Char* end,
                                      Handler&& handler) {
  FMT_ASSERT(begin != end, "");
  auto align = align::none;
  auto p = next_code_point(begin, end);
  if (p == end) p = begin;
  for (;;) {
    switch (static_cast<int>(*p)) {
    case '<':
      align = align::left;
      break;
    ...
    if (align != align::none) {
      if (p != begin) {
        auto c = *begin;
        if (c == '{')
          return handler.on_error("invalid fill character '{'"), begin;
        handler.on_fill(basic_string_view<Char>(begin, to_unsigned(p - begin)));
        begin = p + 1;
      } else
        ++begin;
      handler.on_align(align);
      break;
    } else if (p == begin) {
      break;
    }
    p = begin;
  }
  return begin;
}
```

